import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../app/providers.dart';
class SuppliersScreen extends ConsumerStatefulWidget{const SuppliersScreen({super.key});@override ConsumerState<SuppliersScreen> createState()=>_SuppliersScreenState();}
class _SuppliersScreenState extends ConsumerState<SuppliersScreen>{String query='';bool busy=false;final pulled=<String>{};
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Fournisseurs')),body:FutureBuilder<Map<String,Object?>?>(future:ref.read(businessRepositoryProvider).active(),builder:(context,b){if(b.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final business=b.data;if(business==null)return const Center(child:Text('Créez d’abord une entreprise.'));final id=business['id'].toString();if(pulled.add(id)){ref.read(supplierRepositoryProvider).pullCloud(id).then((_) {if(mounted)setState((){});}).catchError((_){});}return Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Rechercher un fournisseur'),onChanged:(v)=>setState(()=>query=v)),),Expanded(child:FutureBuilder<List<Map<String,Object?>>>(future:ref.read(supplierRepositoryProvider).list(id,query:query),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final rows=s.data??[];if(rows.isEmpty)return const Center(child:Text('Aucun fournisseur'));return ListView.builder(itemCount:rows.length,itemBuilder:(context,i){final x=rows[i];return ListTile(leading:const CircleAvatar(child:Icon(Icons.local_shipping_outlined)),title:Text(x['name'].toString()),subtitle:Text([x['phone'],x['email'],x['address']].where((v)=>v!=null&&v.toString().isNotEmpty).join(' · ')),onTap:()=>_form(id,x),});}))]),floatingActionButton:FloatingActionButton.extended(onPressed:busy?null:()=>_form(null,null),icon:const Icon(Icons.add),label:const Text('Nouveau fournisseur')));
}
Future<void> _form(String? businessId,Map<String,Object?>? item)async{if(busy)return;final b=await ref.read(businessRepositoryProvider).active();if(b==null)return;final id=b['id'].toString();final ctrls=[TextEditingController(text:item?['name']?.toString()??''),TextEditingController(text:item?['phone']?.toString()??''),TextEditingController(text:item?['email']?.toString()??''),TextEditingController(text:item?['address']?.toString()??''),TextEditingController(text:item?['notes']?.toString()??'')];final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,builder:(ctx)=>Padding(padding:EdgeInsets.only(bottom:MediaQuery.viewInsetsOf(ctx).bottom),child:SingleChildScrollView(child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(item==null?'Nouveau fournisseur':'Modifier fournisseur',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:20)),TextField(controller:ctrls[0],decoration:const InputDecoration(labelText:'Nom *')),TextField(controller:ctrls[1],decoration:const InputDecoration(labelText:'Téléphone')),TextField(controller:ctrls[2],decoration:const InputDecoration(labelText:'Email')),TextField(controller:ctrls[3],decoration:const InputDecoration(labelText:'Adresse')),TextField(controller:ctrls[4],decoration:const InputDecoration(labelText:'Notes')),const SizedBox(height:12),SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Enregistrer')))])))));if(ok==true&&ctrls[0].text.trim().isNotEmpty){setState(()=>busy=true);try{final repo=ref.read(supplierRepositoryProvider);if(item==null)await repo.create(businessId:id,name:ctrls[0].text,phone:ctrls[1].text,email:ctrls[2].text,address:ctrls[3].text,notes:ctrls[4].text);else await repo.update(businessId:id,supplierId:item['id'].toString(),name:ctrls[0].text,phone:ctrls[1].text,email:ctrls[2].text,address:ctrls[3].text,notes:ctrls[4].text);try{await ref.read(syncServiceProvider).syncPending();}catch(_){}if(mounted)setState((){});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}for(final c in ctrls)c.dispose();}
}
